def _minimal(title="Minimal", **kw):
    from app.services.synexia.contracts import ReportCardPayload
    return ReportCardPayload(title=title, user_signal="default", **kw)


def test_no_kpis_omits_key_metrics_slide():
    p = _full_payload()
    p.kpis = []
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Key Metrics" not in joined


def test_no_key_findings_omits_key_findings_slide():
    p = _full_payload()
    p.key_findings = []
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Key Findings" not in joined


def test_no_recommendations_omits_recommendations_slide():
    p = _full_payload()
    p.recommendations = []
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Recommendations" not in joined


def test_no_methodology_omits_methodology_slide():
    p = _full_payload()
    p.methodology = ""
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Methodology" not in joined


def test_no_sections_omits_agenda_slide():
    p = _full_payload()
    p.sections = []
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Agenda" not in joined


def test_next_step_never_rendered_even_when_set():
    # next_step is conversational guidance for the in-chat card; it must
    # never appear in the deck regardless of whether it is set.
    p = _full_payload()  # has next_step="Break this down by region?"
    joined = " \n ".join(_all_texts(_slides(_render(p))))
    assert "Next Step" not in joined
    assert "Break this down by region" not in joined


def test_minimal_payload_still_valid_with_cover_only():
    data = _render(_minimal())
    slides = _slides(data)
    assert len(slides) >= 1
    assert "Minimal" in _slide_texts(slides[0])


# ---------------------------------------------------------------------------
# Exporter: density caps
# ---------------------------------------------------------------------------


def test_insights_capped_at_six():
    from app.services.synexia.contracts import InsightSpec
    p = _full_payload()
    p.insights = [InsightSpec(icon="lightbulb", text=f"Insight {i}") for i in range(10)]
    slides = _slides(_render(p))
    # find the Insights slide
    ins_slide = [s for s in slides if any("Insights" == t.strip() for t in _slide_texts(s))]
    assert ins_slide, "Insights slide missing"
    body = [t for t in _slide_texts(ins_slide[0]) if t.startswith("Insight ")]
    assert len(body) <= 6, f"insights not capped: {len(body)}"


def test_recommendations_capped_at_six():
    from app.services.synexia.contracts import InsightSpec
    p = _full_payload()
    p.recommendations = [InsightSpec(icon="check", text=f"Rec {i}") for i in range(10)]
    slides = _slides(_render(p))
    rec_slide = [s for s in slides if any("Recommendations" == t.strip() for t in _slide_texts(s))]
    assert rec_slide, "Recommendations slide missing"
    body = [t for t in _slide_texts(rec_slide[0]) if t.startswith("Rec ")]
    assert len(body) <= 6, f"recommendations not capped: {len(body)}"


def test_key_findings_capped_at_six():
    from app.services.synexia.contracts import InsightSpec
    p = _full_payload()
    p.key_findings = [InsightSpec(icon="target", text=f"Finding {i}") for i in range(10)]
    slides = _slides(_render(p))
    kf_slide = [s for s in slides if any("Key Findings" == t.strip() for t in _slide_texts(s))]
    assert kf_slide, "Key Findings slide missing"
    body = [t for t in _slide_texts(kf_slide[0]) if t.startswith("Finding ")]
    assert len(body) <= 6, f"key findings not capped: {len(body)}"


# ---------------------------------------------------------------------------
# Sandbox generate_pptx
# ---------------------------------------------------------------------------


def test_sandbox_generate_pptx_uses_function_local_imports():
    import app.services.sandbox.sandbox_runner as sr
    src = inspect.getsource(sr.generate_pptx)
    # The sandbox worker forbids MODULE-LEVEL pptx imports; all heavy pptx
    # work now lives inside the vendored layout_engine, which generate_pptx
    # imports lazily (flat copy first, then the in-process dotted path).
    assert "import pptx" not in src, "generate_pptx must not import pptx at module level"
    assert "layout_engine" in src, "generate_pptx must delegate rendering to layout_engine"
    # Confirm no module-level pptx import in sandbox_runner at all.
    module_src = inspect.getsource(sr)
    assert "import pptx" not in module_src, "sandbox_runner must not import pptx at module level"


def test_sandbox_generate_pptx_produces_branded_deck(tmp_path):
    import app.services.sandbox.sandbox_runner as sr
    original = sr.OUTPUT_DIR
    sr.OUTPUT_DIR = tmp_path
    try:
        config = {
            "title": "Sandbox Deck",
            "summary": "A summary from the sandbox.",
            "source": "sandbox_rows",
            "methodology": "Rows aggregated in-process.",
            "kpis": [
                {"label": "Revenue", "value": "100M", "delta": "+5%", "caption": "QoQ"},
                {"label": "Rows", "value": "7", "caption": "distinct"},
            ],
            "insights": [{"icon": "lightbulb", "text": "Sandbox insight."}],
            "key_findings": [{"icon": "target", "text": "Top 3 = 70%."}],
            "recommendations": [{"icon": "check", "text": "Act now."}],
            "next_step": "Drill into region?",
            "chart": {
                "type": "bar", "title": "By material",
                "x_key": "label", "y_keys": ["value"],
                "data": [{"label": "A", "value": 10}, {"label": "B", "value": 20}],
            },
        }
        rows = [{"label": "A", "value": 10}, {"label": "B", "value": 20}]
        out_file = sr.generate_pptx(rows, config, "extra instructions")
        assert out_file == "report.pptx"
        out_path = tmp_path / "report.pptx"
        assert out_path.exists() and out_path.stat().st_size > 0
        data = out_path.read_bytes()
        assert data[:4] == b"PK\x03\x04"
        slides = _slides(data)
        assert len(slides) >= 4, f"sandbox deck too thin: {len(slides)} slides"
        joined = " \n ".join(_all_texts(slides))
        assert "Sandbox Deck" in joined
        assert "Key Metrics" in joined  # kpis present -> KPI slide
        # Phase 1B: the shared layout engine renders decks with subtle slide
        # numbers only — NO "Generated by Zhanlu AI" footer.
        assert "Generated by Zhanlu AI" not in joined
    finally:
        sr.OUTPUT_DIR = original
